from pathlib import Path
from html import escape as e
import json
from validate_html import validate
ROOT=Path(__file__).resolve().parents[1];PUB=ROOT/'public';DATA=json.loads((ROOT/'content/tool-data.json').read_text())
(PUB/'data.mjs').write_text('export const data = '+json.dumps(DATA,ensure_ascii=False)+';\n')
SHIELD='<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M12 22s8-4 8-11V5l-8-3-8 3v6c0 7 8 11 8 11Z"/><path d="m8 12 3 3 5-6"/></svg>'
ARROW='<span aria-hidden="true">↗</span>'
SALES='mailto:sales@resolta.ai?subject=Resolta%20workflow%20review'
PAGES=[]
def link(url,text,cls='text-link'):return f'<a class="{cls}" href="{url}">{text}</a>'
def button(url,text,secondary=False):return link(url,text+' '+ARROW,'button secondary' if secondary else 'button')
def cards(items):return '<div class="cards">'+''.join(f'<article class="card"><span class="step-no">{i+1:02}</span><h3>{t}</h3><p>{d}</p></article>' for i,(t,d) in enumerate(items))+'</div>'
def faq(items):return '<section class="section"><div class="section-heading"><p class="eyebrow">A few useful answers</p><h2>Before you take the next step.</h2></div><div class="faq">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in items)+'</div></section>'
def cta():return '<section class="closing"><div><p class="eyebrow">Start with your workflow</p><h2>Make the next billing decision<br>with a clearer picture.</h2><p>Build a short action plan, or talk to us about your payer and process.</p></div><div class="closing-actions">'+button('/billing-risk-review/','Review my workflow')+link(SALES,'Email sales@resolta.ai','light-link')+'</div></section>'
def hero(eyebrow,title,desc):return f'<div class="page-hero"><p class="eyebrow">{eyebrow}</p><h1>{title}</h1><p class="lead">{desc}</p></div>'
def resources_cards():
 items=[('Checklist','/resources/claim-checklist/','Build a more complete claim review.','Work through 12 evidence checkpoints. Download your progress.','Prepare'),('State explorer','/resources/claim-state-map/','Understand what a claim status means.','See the evidence, limits and next action at each stage.','Follow up'),('Exception finder','/resources/claim-exception-taxonomy/','Turn a billing question into a next step.','Search 10 common issue categories with examples and actions.','Review'),('Cost calculator','/tools/billing-risk-calculator/','Put a number on preparation and rework.','Estimate labor and compare scenarios with your own inputs.','Measure'),('Workflow planner','/billing-risk-review/','Choose a focused place to start.','Create a plan for one payer, process and measurable question.','Prepare'),('Payer-rule method','/methodology/payer-rules/','Know which requirement applies.','Use source, scope and effective dates to structure a review.','Review')]
 return '<div class="resource-grid" id="resource-results">'+''.join(f'<article class="resource-card" data-search="{e((kind+chr(32)+title+chr(32)+desc+chr(32)+tag).lower())}" data-category="{tag}"><div class="resource-top"><span class="pill">{kind}</span><span aria-hidden="true">↗</span></div><h2><a href="{url}">{title}</a></h2><p>{desc}</p><span class="resource-tag">{tag} · Free resource</span></article>' for kind,url,title,desc,tag in items)+'</div>'
def add(path,title,desc,body,kind='commercial',parent=None,script=False):
 PAGES.append(dict(path=path,title=title,description=desc,type=kind,body=body,parent=parent,script=script))
add('/','Catch home care claim errors before you submit','Payer-aware claims and reimbursement software for home care billing teams. Explore the workflow, use free billing tools or speak with Resolta.',f'''
<div class="hero"><div class="hero-copy"><p class="eyebrow"><span class="blue-dot"></span> Claims & reimbursement · Home care</p><h1>Catch claim errors.<br><span>Before you submit.</span></h1><p class="lead">Give your home care billing team a clearer path from source documents to claim review, payer responses and reimbursement.</p><div class="actions">{button('/billing-risk-review/','Review my workflow')}{button('/platform/#walkthrough','Explore the workflow',True)}</div><p class="hero-note">Payer-aware claims and reimbursement software.</p></div>
<div class="claim-preview" aria-label="Illustrative claim review"><div class="preview-heading"><span class="preview-logo">{SHIELD} Claim review</span><span class="pill">Illustration</span></div><div class="preview-body"><div class="preview-label">BEFORE SUBMISSION</div><h2>A clear next step.<br>Not another vague alert.</h2><div class="preview-row"><span class="mini-icon">01</span><div><b>Source information</b><small>Start with the applicable records</small></div><span class="status-tag">Prepare</span></div><div class="preview-row active"><span class="mini-icon">02</span><div><b>Authorization reference</b><small>Confirm against the source record</small></div><span class="status-tag">Review</span></div><div class="review-note"><b>What to do next</b><p>Check the applicable authorization and payer instructions before deciding on a correction.</p></div><div class="preview-row"><span class="mini-icon">03</span><div><b>Reviewer decision</b><small>Record the action and its reason</small></div></div><div class="preview-footer">Illustrative example · Confirm supported payer scope with our team</div></div></div></div>
<div class="principle-strip"><span>Prepare with context</span><span>Review applicable requirements</span><span>Follow the actual response</span></div>
<section class="section"><div class="section-heading"><p class="eyebrow">The work behind reimbursement</p><h2>Less time wondering.<br>More clarity about what comes next.</h2><p>Start with the claim work that creates friction for your team.</p></div>{cards([('Repeated preparation','Identify information that gets re-entered, checked and moved between records.'),('Payer-specific questions','Connect a potential issue to the relevant requirement, evidence and review decision.'),('Unclear claim status','Distinguish receipt, acceptance, adjudication and remittance before choosing a follow-up.')])}</section>
<section class="section two-col"><div><p class="eyebrow">Alongside your current process</p><h2>Make the case for an additional check.</h2><p>Your biller, software and clearinghouse already do important work. Evaluate Resolta against that baseline: which findings are useful, which repeat existing checks, and what still needs investigation?</p>{link('/home-care/','Explore Resolta for home care →')}</div><div class="numbered-list"><div><b>01</b><p><strong>Choose one workflow.</strong> Agree the payer, program and claim route.</p></div><div><b>02</b><p><strong>Compare the work.</strong> Review preparation, corrections and response handling.</p></div><div><b>03</b><p><strong>Decide with evidence.</strong> Measure useful findings and the effort they require.</p></div></div></section>
<section class="section"><div class="section-heading row-heading"><div><p class="eyebrow">Useful before you buy</p><h2>Tools your billing team can use today.</h2></div>{link('/resources/','View all resources →')}</div>{resources_cards()}</section>{cta()}''')
add('/home-care/','Claims software for home care billing teams','A focused approach to home care claim preparation, payer requirements, corrections and reimbursement follow-up.',hero('For home care','A clearer claims workflow.<br>A more focused billing team.','Start with the recurring claim work that takes time away from resolving the next exception.')+f'''<section class="section two-col"><div><h2>Start where the work repeats.</h2><p>Map how your team prepares a claim, checks payer requirements, resolves questions and follows the response. Then identify where another review could add value.</p><p>Authorization and service records provide context where applicable. The focus is the claim and its reimbursement path.</p>{button('/billing-risk-review/','Build my workflow plan')}</div><aside class="callout"><h3>A useful first conversation</h3><ul><li>One specific payer or program</li><li>A recurring preparation or correction problem</li><li>A billing owner who can review the findings</li><li>A comparable sample from your current process</li></ul><p class="small">If your work is mainly private-pay invoicing, start by confirming whether a claims workflow is relevant.</p></aside></section><section class="section"><p class="eyebrow">Where to look</p><h2>Three places to find unnecessary rework.</h2>{cards([('Before preparation','Which source information must be found or entered more than once?'),('Before submission','Which requirements lead to recurring questions or corrections?'),('After a response','Which statuses or unmatched items leave the next action unclear?')])}</section>'''+faq([('Which payers and programs can we evaluate?','Email <a href="mailto:sales@resolta.ai">sales@resolta.ai</a> with your payer, program, jurisdiction and claim route. Our team will confirm supported scope before a pilot.'),('Will this replace our agency management system?','Resolta focuses on claims, payer requirements and reimbursement work. Discuss how it fits alongside the systems your team already uses.'),('Where should we start if our process is already working?','Use the checklist or workflow planner to make your current checks explicit. A comparison can also show that an additional tool is not needed.')])+cta())
add('/platform/','A clearer path from claim preparation to reimbursement','Explore the Resolta claims workflow: source evidence, applicable payer checks, reviewer decisions and claim responses.',hero('The Resolta workflow','Prepare with context.<br>Review with a reason.','Connect the information behind a claim to the requirement being checked and the response that follows.')+'''<section class="section" id="walkthrough"><div class="section-heading"><p class="eyebrow">Explore the process</p><h2>Follow an illustrative review.</h2><p>Select a step to see what a useful claims review should establish. This example uses no customer data.</p></div><div class="workflow-explorer"><div class="step-buttons" aria-label="Workflow steps"><button type="button" data-step="0" aria-pressed="true">01 <span>Prepare</span></button><button type="button" data-step="1" aria-pressed="false">02 <span>Check</span></button><button type="button" data-step="2" aria-pressed="false">03 <span>Resolve</span></button><button type="button" data-step="3" aria-pressed="false">04 <span>Follow</span></button></div><article class="step-panel" id="step-panel" aria-live="polite"><span class="pill">Illustrative workflow</span><h3 id="step-title">Start with the source evidence.</h3><p id="step-copy">Identify the records used to prepare the claim, and make missing information visible before deciding what to do next.</p><div class="example-box"><b>Example</b><p id="step-example">The invoice is available. The applicable authorization still needs to be located in the approved system.</p></div><p class="small" id="step-output">Record to keep: source references and open questions.</p></article></div></section>'''+f'''<section class="section two-col"><div><p class="eyebrow">After submission</p><h2>“Received” is only the beginning.</h2><p>A response should tell you who sent it, which claim attempt it relates to and what it actually establishes. Payer acceptance, adjudication, remittance and cash receipt are different events.</p>{link('/resources/claim-state-map/','Explore the claim-state guide →')}</div><aside class="callout"><h3>Confirm the fit before a pilot.</h3><ul><li>Payer, program and jurisdiction</li><li>Input formats and claim format</li><li>Enrollment and submission route</li><li>Responses and remittance handling</li><li>Billing-team review responsibilities</li></ul>{link(SALES,'Discuss your workflow →')}</aside></section>'''+faq([('Why add this if our clearinghouse checks claims?','Compare an additional review with the checks you already have. Useful findings, duplicate alerts, false alerts and missing information all belong in that comparison.'),('Does passing a check guarantee payment?','No. A scoped check addresses a particular requirement. Payer adjudication and payment depend on additional factors.'),('Can we see our workflow demonstrated?','Email sales@resolta.ai with your payer and process. Confirm the supported route and an appropriate demonstration with the team. Do not send patient or claim details by email.')])+cta(),script=True)
add('/pricing/','Pricing built around your claims workflow','Discuss payer scope, claim volume, implementation and pilot terms with Resolta sales.',hero('Pricing','Start with the workflow.<br>Then agree the right scope.','Get a quote based on your payer, process and implementation needs. Agree the terms before a pilot begins.')+f'''<section class="quote-panel"><div><p class="eyebrow">Talk to our team</p><h2>What would a useful pilot look like?</h2><p>Send us a brief description of your organization’s billing workflow. Include the payer or program, approximate claim volume and the part of the process you want to improve.</p><p>No patient information or claim files are needed.</p>{button(SALES,'Email sales@resolta.ai')}</div><div class="quote-list"><h3>Your quote should cover</h3><ul><li>Supported workflow and expected usage</li><li>Implementation and enrollment responsibilities</li><li>Pilot and recurring fees</li><li>Support, term and exit conditions</li><li>How you will evaluate the result</li></ul></div></section><section class="section"><h2>Put a baseline behind the decision.</h2><p>Estimate the work your team already does. Compare an alternative using observed time and its full costs, including fees and implementation.</p>{button('/tools/billing-risk-calculator/','Estimate workflow costs',True)}</section>'''+faq([('Is there a standard rate on this website?','Pricing is quoted for the agreed scope. Contact sales@resolta.ai to discuss your workflow and request written terms.'),('What should we measure during an evaluation?','Use comparable claims and time periods. Track preparation and correction time, useful findings, duplicate checks and false alerts. Include any new software or service costs.'),('Is the workflow planner free to use?','Yes. The public planner, checklist, status guide and calculator are available without an account.')]))
add('/billing-risk-review/','Review your claims workflow','Create a focused claims-workflow action plan, download it and choose whether to discuss it with Resolta sales.',hero('Free workflow planner','Find a useful place to start.','Answer four questions about your process. Get a focused action plan you can download or discuss with your team.')+'''<div class="privacy-strip">No patient details. No account required. Your answers stay in this page until you choose to download or email them.</div><section class="section planner-layout"><form id="planner" class="form-card"><h2>Your current workflow</h2><label for="program">Payer or program focus</label><select id="program" name="program" required><option value="">Choose a focus</option><option value="va">VA Community Care</option><option value="medicaid">Medicaid</option><option value="commercial">Commercial payer</option><option value="other">Other or not yet sure</option></select><p class="field-help">This sets review context; it does not confirm product coverage.</p><label for="volume">Approximate claims per month</label><select id="volume" name="volume" required><option value="">Choose a range</option><option value="low">Fewer than 50</option><option value="medium">50–250</option><option value="high">251–1,000</option><option value="large">More than 1,000</option></select><label for="focus">Where does work get stuck?</label><select id="focus" name="focus" required><option value="">Choose the main issue</option><option value="prepare">Finding or re-entering source information</option><option value="review">Payer questions or repeated corrections</option><option value="status">Understanding responses and next steps</option><option value="reconcile">Matching remittances and payments</option></select><label for="baseline">Do you have a measured time baseline?</label><select id="baseline" name="baseline" required><option value="">Choose one</option><option value="yes">Yes, we have observed timings</option><option value="no">Not yet</option></select><button type="submit" class="button">Create my action plan <span aria-hidden="true">→</span></button><p class="small">General planning guidance. Confirm payer-specific requirements with current sources.</p></form><div class="plan-output" id="plan-output" tabindex="-1" aria-label="Your workflow plan" aria-live="polite"><p class="eyebrow">Your next step</p><h2>A focused plan,<br>not a generic score.</h2><p>Your plan will identify an initial question, the evidence to gather, a way to measure the work and useful tools for your next step.</p><div class="empty-steps"><span>01 · Define the question</span><span>02 · Gather evidence</span><span>03 · Compare the work</span></div></div></section>'''+f'''<section class="section two-col"><div><h2>Prefer a conversation?</h2><p>Tell us about your payer and billing process. We’ll discuss fit and scope before any claim-level information is shared.</p>{button(SALES,'Email sales@resolta.ai')}</div><div><h3>Keep the first review manageable.</h3><p>Choose one payer/program and a recent period. A sample of roughly 25–50 claims may be a practical starting point; use a smaller or different sample when the workflow calls for it.</p>{link('/downloads/review-scope.txt','Download the blank review worksheet →')}</div></section>''',kind='tool',script=True)
add('/resources/','Free tools for home care billing teams','Use Resolta’s claim checklist, exception finder, state explorer, workflow planner and labor-cost calculator.',hero('The billing workbench','A useful next step.<br>For the question in front of you.','Practical, ungated tools for preparation, review, follow-up and measurement.')+'''<div class="resource-filters"><div><label for="resource-search">Find a resource</label><input id="resource-search" type="search" placeholder="Try corrections or claim status"></div><div><label for="resource-category">Workflow stage</label><select id="resource-category"><option>All stages</option><option>Prepare</option><option>Review</option><option>Follow up</option><option>Measure</option></select></div></div><p id="resource-count" class="small" role="status">6 resources</p>'''+resources_cards()+'''<p id="resource-empty" class="empty-result" hidden>No resources match that search. Try a different term or choose All stages.</p><section class="section"><h2>Not sure which tool to use?</h2><p>Start with the workflow planner. It will point you toward an initial question and the evidence to gather.</p>'''+button('/billing-risk-review/','Build my workflow plan')+'</section>',kind='resource',script=True)
checkrows=''.join(f'<label class="check-row"><input type="checkbox" name="checkpoint" value="{i}"><span><b>{i+1:02} · {e(t)}</b><span>{e(d)}</span></span></label>' for i,(t,d) in enumerate(DATA['checklist']))
add('/resources/claim-checklist/','Interactive home care claim checklist','Work through 12 general evidence checkpoints, keep track of open items and download a checklist for your billing team.',hero('Preparation tool','Give every claim review<br>a clear starting point.','Work through the evidence your process needs. Check off the steps you have reviewed and download the remaining items.')+'''<div class="privacy-strip">Use this as a process checklist. Keep patient and claim identifiers in your approved secure system.</div><section class="section checklist-layout"><div><h2>12 review checkpoints</h2><p class="small">Checkpoints reviewed here are not a payer approval or a guarantee of payment.</p><div id="checklist">'''+checkrows+'''</div></div><aside class="sticky-card"><p class="eyebrow">Your progress</p><h2 id="check-count" role="status">0 of 12 reviewed</h2><progress id="check-progress" value="0" max="12" aria-label="Checkpoints reviewed"></progress><p id="check-remaining">12 checkpoints left to review.</p><button class="button" type="button" id="download-checklist">Download my checklist ↓</button><button class="plain-button" type="button" id="reset-checklist">Reset checklist</button><p id="check-download-status" class="small" role="status"></p><p class="small">Selections clear when you reload this page. Download a copy to keep your progress.</p></aside></section>'''+f'''<section class="section two-col"><div><h2>An item is unresolved. What next?</h2><p>Name the question, identify the evidence needed and assign a next action in your billing workflow.</p>{link('/resources/claim-exception-taxonomy/','Find the relevant exception category →')}</div><div><h3>Using this with your team</h3><p>Confirm the payer, program, jurisdiction, service dates and submission route first. Apply current requirements from the relevant payer source; this general checklist is not a payer rulebook.</p>{link('/downloads/claim-checklist.txt','Download a blank text checklist →')}</div></section>''',kind='resource',parent='Resources',script=True)
statebuttons=''.join(f'<button type="button" data-state="{s["id"]}" aria-pressed="{"true" if i==0 else "false"}"><span>{i+1:02}</span>{e(s["label"])}</button>' for i,s in enumerate(DATA['states']))
first=DATA['states'][0]
add('/resources/claim-state-map/','Claim status explorer: from draft to cash','Understand the evidence behind claim transmission, acknowledgments, payer acceptance, adjudication, remittance and cash reconciliation.',hero('Claim status explorer','A status is a clue.<br>Know what it actually proves.','Choose a state to see the evidence behind it, its limits and a useful next action.')+f'''<section class="section state-layout"><div class="state-buttons" aria-label="Claim states">{statebuttons}</div><article class="state-detail" id="state-detail" aria-live="polite"><p class="eyebrow">Evidence → meaning → action</p><h2 id="state-label">{first['label']}</h2><dl><dt>Evidence to look for</dt><dd id="state-evidence">{first['evidence']}</dd><dt>What it means</dt><dd id="state-meaning">{first['meaning']}</dd><dt>What it does not establish</dt><dd id="state-limit">{first['limit']}</dd></dl><div class="next-action"><h3>Next action</h3><p id="state-next">{first['next']}</p></div></article></section><section class="section two-col"><div><h2>Claims do not always move in a straight line.</h2><p>A rejection can lead to a corrected submission. Adjudication can include denial or adjustments. Preserve the earlier attempt and response when another step follows.</p></div><div><h3>Read the sender, not just the label.</h3><p>Clearinghouse and payer acknowledgments can describe different points in the route. A 277CA acknowledgment is different from an 835 remittance. Neither replaces reconciliation of a bank receipt.</p></div></section><div class="source-note"><b>Sources and scope</b><p>General educational guide, reviewed 7 October 2026. See <a href="https://www.stedi.com/docs/healthcare/claim-responses-overview">Stedi’s acknowledgment and ERA documentation</a> and <a href="https://www.stedi.com/docs/providers/providers-claims-view">claims-view documentation</a>. Confirm the meaning of the actual response in your workflow.</p></div>''',kind='resource',parent='Resources',script=True)
exc=''.join(f'''<article class="exception-card" data-search="{e(' '.join(str(v) for v in x.values()).lower())}" data-phase="{x['phase']}"><div class="exception-meta"><span class="pill">{x['phase']}</span><span>{x['id']}</span></div><h2>{x['title']}</h2><p>{x['symptom']}</p><details><summary>Example & next action</summary><div class="exception-content"><h3>Example</h3><p>{x['example']}</p><h3>Next action</h3><p>{x['action']}</p><h3>Evidence to keep</h3><p>{x['evidence']}</p><p class="caution">{x['avoid']}</p></div></details></article>''' for x in DATA['exceptions'])
add('/resources/claim-exception-taxonomy/','Claim exception finder: examples and next actions','Search common claim-review questions, see practical examples and identify the evidence and next action for your billing team.',hero('Claim exception finder','Name the issue.<br>Find the next useful action.','Search by a symptom or filter by workflow stage. Each category includes an example, evidence to look for and a next step.')+'''<div class="resource-filters"><div><label for="exception-search">What are you investigating?</label><input id="exception-search" type="search" placeholder="Try authorization, missing record or deposit"></div><div><label for="exception-phase">Workflow stage</label><select id="exception-phase"><option>All stages</option><option>Prepare</option><option>Review</option><option>Submit</option><option>Follow up</option><option>Reconcile</option></select></div></div><div class="result-toolbar"><p id="exception-count" role="status">10 categories</p><button type="button" class="plain-button" id="reset-exceptions">Clear filters</button></div><div class="exception-grid" id="exception-results">'''+exc+'''</div><p class="empty-result" id="exception-empty" hidden>No categories match. Try a shorter search or clear the filters.</p><section class="section two-col"><div><h2>Make the handoff actionable.</h2><p>Record the question, applicable source, reviewer decision, owner and next step in your approved secure system. Missing evidence needs investigation before it can be called an error.</p><a class="button secondary" href="/downloads/exception-log.csv" download>Download an exception-log template ↓</a></div><div><h3>Use categories consistently.</h3><p>These categories help organize a review. They are not measured error rates, a severity score or a substitute for payer-specific instructions.</p><a class="text-link" href="/methodology/payer-rules/">See the payer-rule method →</a></div></section>''',kind='resource',parent='Resources',script=True)
def num(id,label,value,max,help='',integer=False):return f'<div><label for="{id}">{label}</label><input type="number" id="{id}" name="{id}" value="{value}" min="0" max="{max}" step="{1 if integer else "0.01"}" aria-describedby="{id}-range" required><p class="field-help" id="{id}-range">0–{max:,}{chr(32)+"(whole claims)" if integer else ""}</p>'+ (f'<p class="field-help">{help}</p>' if help else '')+'</div>'
add('/tools/billing-risk-calculator/','Claim preparation and correction cost calculator','Estimate monthly claim preparation and correction labor. Compare a second scenario including fees and implementation costs.',hero('Workflow cost calculator','Know the cost of the work.<br>Then compare the alternatives.','Use your own observations to estimate labor. Add a comparison when you have equivalent timings and full costs.')+'''<div class="privacy-strip">Calculations happen in this page. Inputs are not submitted to Resolta.</div><section class="section calculator-layout"><form id="cost" class="form-card"><h2>Your monthly baseline</h2><div class="field-grid">'''+num('volume','Claims prepared per month',100,1000000,integer=True)+num('prep','Preparation minutes per claim',10,10080)+num('corrections','Claims corrected per month',20,1000000,'May include claims from an older period.',True)+num('minutes','Total correction minutes per affected claim',15,10080,'Include repeat correction attempts; exclude initial preparation.')+num('rate','Loaded labor cost per hour ($)',30,10000) +'''</div><label class="check-inline"><input type="checkbox" id="compare-toggle">Add a comparison scenario</label><fieldset id="comparison-fields" disabled hidden><legend>Comparison — same volume and hourly rate</legend><p class="small">Use equivalent work and measured timings. Enter all incremental monthly costs.</p><div class="field-grid">'''+num('compare-prep','Comparison preparation minutes',8,10080)+num('compare-corrections','Comparison claims corrected',20,1000000,integer=True)+num('compare-minutes','Comparison correction minutes',12,10080)+num('fees','Additional software/service fees ($ per month)',0,100000000)+num('implementation','Implementation cost allocated to this month ($)',0,100000000)+'''</div></fieldset><button class="button" type="submit">Calculate costs →</button><p class="form-error" id="calc-error" role="alert"></p></form><aside class="cost-output"><p class="eyebrow">Your estimate</p><h2>See where the time goes.</h2><div id="result" tabindex="-1" aria-label="Calculated cost estimate" aria-live="polite"><p>Calculate a scenario to see preparation hours, correction hours and monthly labor cost.</p></div><button class="button secondary" type="button" id="save" disabled>Download calculation ↓</button><p id="saveStatus" class="small" role="status"></p><p class="small">This estimates labor and costs. It does not predict payment, recoverable revenue or Resolta savings.</p></aside></section><section class="section"><h2>The math is visible.</h2><div class="formula-grid"><div><b>Preparation hours</b><p>Claims × preparation minutes ÷ 60</p></div><div><b>Correction hours</b><p>Corrected claims × total correction minutes ÷ 60</p></div><div><b>Monthly labor cost</b><p>Total hours × loaded hourly cost</p></div><div><b>Net monthly difference</b><p>Baseline labor − comparison labor − additional fees − allocated implementation cost</p></div></div><p>A negative comparison means the alternative costs more. Use comparable work and account for sampling differences before making a decision.</p></section>''',kind='tool',parent='Resources',script=True)
add('/methodology/payer-rules/','How to evaluate a payer requirement','Use the current source, applicable program, effective dates and a documented reviewer decision to evaluate payer-rule questions.',hero('Our evaluation method','A requirement needs<br>a source and a scope.','A useful finding explains which instruction applies, what evidence supports it and what the reviewer should investigate.')+'''<section class="section">'''+cards([('Start with the source','Use current primary payer or program instructions. Keep the section and the date it was checked.'),('Confirm applicability','Check payer, program, jurisdiction, service, claim format and effective period.'),('Keep the decision','Document the evidence, uncertainty, reviewer decision and next action.')])+'''</section><section class="section two-col"><div><h2>What makes an alert useful?</h2><p>It identifies a concrete question and the evidence needed to resolve it. A review should also recognize when a check is duplicated, an alert is false or the information is unavailable.</p><a class="text-link" href="/resources/claim-exception-taxonomy/">Explore issue categories →</a></div><aside class="callout"><h3>When guidance is unclear</h3><p>Record the conflict or missing effective date. Have the appropriate reviewer confirm the instruction before applying it to a claim.</p><p>Public educational material describes a method; it does not establish that a particular payer route is supported by the software.</p></aside></section>'''+faq([('Does a passed check guarantee payment?','No. A check addresses a defined requirement. Adjudication, coverage, documentation and other factors still affect payment.'),('How should we evaluate additional checks?','Compare with the current process using equivalent scope. Count useful findings, duplicate checks, false alerts and unavailable evidence, as well as the work needed to review them.')])+cta(),kind='methodology')
add('/about/','About Resolta','Resolta focuses on claims, payer requirements, billing workflow and reimbursement, starting with home care.',hero('About Resolta','Clarity for the people<br>behind reimbursement.','Resolta focuses on the work between preparing a claim and understanding what happens to it.')+'''<section class="section two-col"><div><p class="eyebrow">Our starting point</p><h2>Built around the billing question.</h2><p>What needs attention before this claim goes out? Which requirement applies? What does this response mean? Who should act next?</p><p>These are the practical questions that guide Resolta’s claims and reimbursement focus. Home care is our initial market.</p></div><div class="callout"><h3>Our focus</h3><ul><li>Claim preparation and review</li><li>Applicable payer requirements</li><li>Billing-team decisions and corrections</li><li>Submission responses and follow-up</li><li>Reimbursement and revenue protection</li></ul></div></section><section class="section"><h2>Useful work should be demonstrable.</h2><p>Evaluate an additional tool against the process you already have. Use a defined workflow, current evidence and comparable measures. The result should help your team make a better decision, even when that decision is to keep the current process.</p><a class="button" href="mailto:sales@resolta.ai?subject=Resolta%20introduction">Talk to our team ↗</a></section>''',kind='brand')
add('/privacy/','How Resolta public tools handle your information','Learn what happens to information used in Resolta’s public workflow planner, checklist and calculator.',hero('Public tool privacy','Useful tools.<br>No claim data required.','This page explains the current public website tools and how to contact Resolta about them.')+'''<section class="section prose"><h2>Planner, checklist and calculator</h2><p>Tool entries are processed in your browser page. These tools do not submit the entries to Resolta, save them to browser storage or upload claim files. Reloading the page clears the entries. A download saves a copy on your device.</p><h2>Choosing to email</h2><p>Email buttons open your configured email application. You review and send the message yourself. If you email a workflow plan, the selected process answers appear in that draft. Do not include patient names, member identifiers, claim files or other sensitive details.</p><h2>Website requests</h2><p>Loading this website makes ordinary network requests to our hosting service. Hosting infrastructure may process technical request information, such as IP addresses and requested pages. The public tools do not load advertising trackers or send their input values to an analytics service.</p><h2>The application is separate</h2><p>The authenticated Resolta application has a different purpose and handles information according to the applicable customer arrangements. This page describes the public website tools, not the application’s contractual data terms.</p><h2>Questions</h2><p>Contact <a href="mailto:sales@resolta.ai">sales@resolta.ai</a> for the appropriate privacy or customer-data contact before sharing sensitive information.</p><p class="small">Last updated: 7 October 2026.</p></section>''',kind='information')
nav=[('/home-care/','Home care'),('/platform/','Platform'),('/resources/','Resources'),('/pricing/','Pricing')]
