 bread='' if path=='/' else '<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a><span aria-hidden="true">/</span>'+('<a href="/resources/">Resources</a><span aria-hidden="true">/</span>' if p['parent'] else '')+f'<span aria-current="page">{title}</span></nav>'
