 target=PUB/(path.strip('/')+'/index.html' if path!='/' else 'index.html');target.parent.mkdir(parents=True,exist_ok=True);target.write_text(head+bread+p['body']+('<noscript><p class="privacy-strip">Enable JavaScript to use the interactive tools. You can still read the guides, download the blank checklist and email sales@resolta.ai.</p></noscript>' if p['script'] else '')+foot)
